CREATE TABLE IF NOT EXISTS assistant_customer_changes (oa_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(oa_id,customer_id));
CREATE INDEX IF NOT EXISTS customer_links_customer ON customer_links(customer_id,oa_id,state);
CREATE INDEX IF NOT EXISTS customer_links_oa_customer ON customer_links(oa_id,customer_id,state);
CREATE TRIGGER IF NOT EXISTS assistant_customer_updated AFTER UPDATE OF name,owner_user_id,team_id,mode,stage,opt_out,version ON customers BEGIN INSERT INTO assistant_customer_changes(oa_id,customer_id) SELECT oa_id,customer_id FROM customer_links WHERE customer_id=NEW.id ON CONFLICT(oa_id,customer_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS assistant_link_insert AFTER INSERT ON customer_links BEGIN INSERT INTO assistant_customer_changes(oa_id,customer_id) VALUES (NEW.oa_id,NEW.customer_id) ON CONFLICT(oa_id,customer_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS assistant_link_update AFTER UPDATE ON customer_links BEGIN INSERT INTO assistant_customer_changes(oa_id,customer_id) VALUES (OLD.oa_id,OLD.customer_id) ON CONFLICT(oa_id,customer_id) DO UPDATE SET revision=revision+1; INSERT INTO assistant_customer_changes(oa_id,customer_id) VALUES (NEW.oa_id,NEW.customer_id) ON CONFLICT(oa_id,customer_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS assistant_link_delete AFTER DELETE ON customer_links BEGIN INSERT INTO assistant_customer_changes(oa_id,customer_id) VALUES (OLD.oa_id,OLD.customer_id) ON CONFLICT(oa_id,customer_id) DO UPDATE SET revision=revision+1; END;
